enum Message { Increment, Refresh, LoadFailed(String) }

#[derive(Default)]
struct Model { count: i32, loading: bool }

fn update(model: &mut Model, msg: Message) {
    match msg {
        Message::Increment     => model.count += 1,
        Message::Refresh       => model.loading = true,
        Message::LoadFailed(_) => model.loading = false,
    }
}
